/* ============================================================================
   EXTEND image_cdn_map — the 1314 accessory images left on Salsify
   2026-09-22

   The 2026-09-17 repoint (migrations/2026-09-17_repoint_product_images_to_bunny.sql)
   left these behind because their masters were never on Bunny. They are now in
   Salsify_Masters_Native and uploaded by jmv_sync/bunny_upload_mac.sh.
   Source: OnlineSmartPOS/jm_missing_bunny_map.csv (1314 rows, 470 SKUs).

   ⚠ PREREQUISITE: the upload must be finished first. Check STEP 1 in a browser.
   Otherwise these products point at objects that do not exist and go blank.
   ============================================================================ */

/* --- STEP 1 — spot-check three objects in a BROWSER --------------------------
   https://images.bathroomvanitiesoutlet.com/E444-BC15-GW/addison-15-in-base-cabinet-only-glossy-white-e444-bc15-gw-1.webp
   https://images.bathroomvanitiesoutlet.com/WS-1-NVB/wood-sample-navy-blue-ws-1-nvb-1.webp
   https://images.bathroomvanitiesoutlet.com/050-BS72-ENC/72-in-backsplash-3-cm-ethereal-noctis-050-bs72-enc-1.webp
   All three must show an image.
   -------------------------------------------------------------------------- */

/* --- STEP 2 — extend the map. INSERT IGNORE: re-running is harmless. ------- */

/* --- STEP 3 — rows that CAN now be repointed (read only) ------------------- */
SELECT COUNT(*) AS rows_with_a_mapping
FROM product_images pi
JOIN products p ON p.id = pi.product_id
JOIN image_cdn_map m
  ON  m.sku = p.sku
  AND m.source_key = SUBSTRING_INDEX(
        SUBSTRING_INDEX(SUBSTRING_INDEX(pi.url, '?', 1), '/', -1), '.', 1)
WHERE pi.url LIKE '%images.salsify.com%';

/* --- STEP 4 — THE WRITE (same statement as the 2026-09-17 repoint) --------- */
UPDATE product_images pi
JOIN products p ON p.id = pi.product_id
JOIN image_cdn_map m
  ON  m.sku = p.sku
  AND m.source_key = SUBSTRING_INDEX(
        SUBSTRING_INDEX(SUBSTRING_INDEX(pi.url, '?', 1), '/', -1), '.', 1)
SET pi.url = CONCAT('https://images.bathroomvanitiesoutlet.com/', p.sku, '/', m.filename)
WHERE pi.url LIKE '%images.salsify.com%';
/*  Affected rows should equal STEP 3. If lower, stop and say so. */

/* --- STEP 5 — verify ------------------------------------------------------- */
SELECT
  SUM(url LIKE '%images.bathroomvanitiesoutlet.com%') AS on_bunny,
  SUM(url LIKE '%images.salsify.com%')                AS still_salsify,
  COUNT(*)                                            AS total_rows
FROM product_images;

/*  AFTERWARDS: re-run searchSync so search results stop pointing at Salsify. */
